"Core app tools are available in new Codex tasks and their continuations. Older tasks keep their original catalog. When enabled, Jev joins new and resumed tasks across connected harnesses. App actions use your approval mode; embedded browser controls require the task to be visible.": "Основные инструменты приложения доступны в новых задачах Codex и их продолжениях. Старые задачи сохраняют исходный каталог. После включения Jev присоединяется к новым и возобновленным задачам во всех подключенных Agent. Действия приложения используют ваш режим одобрения; встроенные элементы управления браузером требуют, чтобы задача была видима.",
