"Optional · selected task evidence is sent to TypeSafe when you run. Provider usage charges apply. PandaCode works without Jev. Advice does not change files, models, or permissions.": "Опционально · при запуске выбранные доказательства задачи отправляются в TypeSafe. Применяются тарифы провайдера. PandaCode работает и без Jev. Советы не меняют файлы, модели или разрешения.",
"Optional, such as us-central1": "Опционально, например us-central1",
"Optional. Leave blank for no token limit.": "Опционально. Оставьте пустым, чтобы не ограничивать token.",
"Optional. Tone, values and conversational style, kept apart from the instructions. Importing copies the file once; later changes to the file do not change the bot. Personality never grants tools or permissions.": "Опционально. Тон, ценности и стиль общения, хранятся отдельно от указаний. Импорт копирует файл один раз; последующие изменения файла не меняют Bot. Характер никогда не дает инструментов или разрешений.",
