"PandaCode has no “{0}” view. Showing its data instead.": "В PandaCode нет представления \"{0}\". Показаны его данные.",
"PandaCode quick launcher": "Быстрый лаунчер PandaCode",
"PandaCode restarts when your agents are done and you step away.": "PandaCode перезапустится, когда ваши Agent закончат и вы отойдете.",
"PandaCode runs Linux and macOS VMs on Apple's Virtualization framework: headless, and only the memory you give it.": "PandaCode запускает VM Linux и macOS на фреймворке виртуализации Apple: без экрана и только с выделенной вами памятью.",
"PandaCode tools": "Инструменты PandaCode",
"PandaCode uses it to check that messages really come from Meta.": "PandaCode использует его, чтобы проверять, что сообщения действительно приходят от Meta.",
"PandaCode will restart to update when your agents finish.": "Когда ваши Agent закончат, PandaCode перезапустится для обновления.",
"PandaCode works without Jev or a TypeSafe key. Optional decision assistance only needs the key for the provider you pick. OpenRouter models are listed only when you open the model menu. Keys are saved privately on this device, outside the keychain. Leave a field empty to keep its saved key.": "PandaCode работает без Jev и ключа TypeSafe. Необязательной помощи в решениях нужен только ключ выбранного провайдера. Модели OpenRouter перечисляются, только когда вы открываете меню моделей. Ключи сохраняются приватно на этом устройстве, вне связки ключей. Оставьте поле пустым, чтобы сохранить прежний ключ.",
"PandaCode {0} is available.": "Доступен PandaCode {0}.",
