"Reads account limits from your locally configured agent accounts. Requests go directly to the provider or its CLI, never through PandaCode servers. No prompts are sent. Results are cached for one minute; Refresh is limited to once every ten seconds per provider. Some providers do not expose their limits. Usage is shared with other apps using the same account.": "Читает лимиты аккаунтов из ваших локально настроенных аккаунтов Agent. Запросы идут напрямую к провайдеру или его CLI, никогда через серверы PandaCode. Запросы не отправляются. Результаты кэшируются на одну минуту; обновление ограничено одним разом в десять секунд на провайдера. Некоторые провайдеры не раскрывают лимиты. Использование делится с другими приложениями того же аккаунта.",
