"Team mode: your selected model becomes the lead. It plans the work, starts other agents in parallel, picks a model for each worker on its own, and reviews their results. To choose the workers yourself, just say so in your prompt, like \"use Sonnet 5.5 workers\" or \"have Codex review it\". Click to turn Team on or off.": "Командный режим: ваша выбранная модель становится Lead. Она планирует работу, параллельно запускает других Agent, сама подбирает модель каждому worker и проверяет их результаты. Чтобы выбрать worker самостоятельно, просто скажите об этом в запросе, например \"используй worker на Sonnet 5.5\" или \"пусть Codex проверит\". Нажмите, чтобы включить или выключить Team.",
