"Use Copilot Agent mode with Allow All on. Copilot automatically approves tool, path, and URL requests.": "Используйте режим Copilot Agent с включенным Allow All. Copilot автоматически одобряет запросы инструментов, путей и URL.",
"Use Copilot Plan mode. Read, search, fetch, and think requests are allowed; other permission requests are declined.": "Используйте режим Copilot Plan. Запросы на чтение, поиск, получение и размышление разрешены; остальные запросы разрешений отклоняются.",
