"Hermes works in this project. Asks you before terminal commands or dangerous actions.": "Hermes работает в этом проекте. Спрашивает вас перед командами терминала или опасными действиями.",
"Skip approval prompts: Hermes runs every tool without asking (equivalent to its --yolo).": "Пропускать запросы одобрения: Hermes запускает любой инструмент без вопросов (эквивалент его --yolo).",
