"Team mode: your selected model becomes the lead. It plans the work, starts other agents in parallel and reviews their results. Cheap, Balanced and Best set how Panda Router picks each worker's model; with routing off the lead picks a model for each worker on its own. To choose the workers yourself, just say so in your prompt, like \"use Sonnet 5.5 workers\" or \"have Codex review it\".": "Командный режим: ваша выбранная модель становится Lead. Она планирует работу, параллельно запускает других Agent и проверяет их результаты. Cheap, Balanced и Best задают, как Panda Router выбирает модель каждому worker; при выключенной маршрутизации Lead сам подбирает модель каждому worker. Чтобы выбрать worker самостоятельно, просто скажите об этом в запросе, например \"используй worker на Sonnet 5.5\" или \"пусть Codex проверит\".",
