"That doesn't look like a Telegram bot token. It looks like 123456789:AAE… — copy the whole line BotFather sent.": "Это не похоже на токен Bot Telegram. Он выглядит как 123456789:AAE… - скопируйте всю строку, которую прислал BotFather.",
