"The agent's release channel changed. Check for updates again.": "Канал релизов Agent изменился. Проверьте обновления снова.",
"The app-level token starts with xapp-. Create it under Basic Information → App-Level Tokens with the connections:write scope.": "Токен уровня приложения начинается с xapp-. Создайте его в Basic Information → App-Level Tokens с областью connections:write.",
"The bot token starts with xoxb-. Find it under OAuth & Permissions → Bot User OAuth Token (install the app first).": "Токен Bot начинается с xoxb-. Найдите его в OAuth & Permissions → Bot User OAuth Token (сначала установите приложение).",
