"The saved collaboration mode is invalid.": "Сохраненный режим совместной работы недопустим.",
"The saved evidence changed. Preview it again before running Jev.": "Сохраненные доказательства изменились. Посмотрите их заново перед запуском Jev.",
"The selected Claude model does not support this reasoning effort. Choose another effort or use harness settings.": "Выбранная модель Claude не поддерживает этот уровень рассуждений. Выберите другой уровень или используйте настройки Agent.",
"The selected Codex model does not support this reasoning effort. Choose another effort or use harness settings.": "Выбранная модель Codex не поддерживает этот уровень рассуждений. Выберите другой уровень или используйте настройки Agent.",
